syntax:
Function returning an object by value:

```c++
MyClass myFunction() {
  MyClass obj; 
  // ... some operations on obj ...
  return obj; 
}
```

Compiler might perform RVO by directly constructing the `MyClass` object at the caller's memory location, avoiding a copy or move.

code_example:
#include <iostream>
#include <string>
struct MyClass {
  std::string data; 
  MyClass(const std::string& d) : data(d) { std::cout << "MyClass constructor called\n"; }
  MyClass(MyClass&& other) noexcept : data(std::move(other.data)) { std::cout << "MyClass move constructor called\n"; }
  MyClass(const MyClass& other) : data(other.data) { std::cout << "MyClass copy constructor called\n"; }
};
MyClass myFunction() {
  MyClass obj("Hello");
  return obj;
}
int main() {
  MyClass result = myFunction();
  std::cout << result.data << "\n";
  return 0;
}
